# Template HTML embutido
HTML_PAGE = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>Studio Video AI - Painel Profissional de V\u00eddeos</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@500;700&display=swap\" rel=\"stylesheet\">\n  \n  <style>\n    /* ==========================================================\n       TEMA PROFISSIONAL WORDPRESS / SAAS MODERNO (DARK STUDIO)\n       ========================================================== */\n    :root {\n      --bg-body: #0b0f19;\n      --bg-surface: #111827;\n      --bg-card: #1f2937;\n      --bg-card-hover: #283548;\n      --bg-input: #0f172a;\n      \n      --primary: #6366f1;\n      --primary-hover: #4f46e5;\n      --primary-glow: rgba(99, 102, 241, 0.35);\n      --accent: #06b6d4;\n      --accent-glow: rgba(6, 182, 212, 0.3);\n      --success: #10b981;\n      --danger: #ef4444;\n      \n      --border-subtle: rgba(255, 255, 255, 0.08);\n      --border-focus: #6366f1;\n      \n      --text-main: #f9fafb;\n      --text-muted: #9ca3af;\n      --text-subtle: #6b7280;\n      \n      --radius-sm: 8px;\n      --radius-md: 12px;\n      --radius-lg: 18px;\n      --shadow-card: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.4);\n      --transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n\n    body {\n      font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;\n      background-color: var(--bg-body);\n      color: var(--text-main);\n      line-height: 1.5;\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n    }\n\n    /* Trava e normaliza TODOS os SVGs para que NUNCA fiquem desproporcionais */\n    svg {\n      display: inline-block !important;\n      vertical-align: middle !important;\n      max-width: 36px !important;\n      max-height: 36px !important;\n      width: 22px !important;\n      height: 22px !important;\n      flex-shrink: 0 !important;\n    }\n    svg.icon-sm { width: 16px !important; height: 16px !important; }\n    svg.icon-md { width: 22px !important; height: 22px !important; }\n    svg.icon-lg { width: 36px !important; height: 36px !important; }\n\n    .icon-sm { width: 16px; height: 16px; }\n    .icon-md { width: 22px; height: 22px; }\n    .icon-lg { width: 36px; height: 36px; }\n\n    /* Header / Navbar */\n    .wp-navbar {\n      background: rgba(17, 24, 39, 0.95);\n      backdrop-filter: blur(12px);\n      border-bottom: 1px solid var(--border-subtle);\n      position: sticky;\n      top: 0;\n      z-index: 100;\n      padding: 14px 24px;\n    }\n\n    .navbar-container {\n      max-width: 1280px;\n      margin: 0 auto;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      text-decoration: none;\n      color: inherit;\n    }\n\n    .brand-logo {\n      width: 40px;\n      height: 40px;\n      border-radius: var(--radius-md);\n      background: linear-gradient(135deg, var(--primary), var(--accent));\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      box-shadow: 0 0 16px var(--primary-glow);\n    }\n\n    .brand-logo svg {\n      width: 22px;\n      height: 22px;\n      fill: #ffffff;\n      color: #ffffff;\n    }\n\n    .brand-title {\n      font-size: 1.25rem;\n      font-weight: 800;\n      letter-spacing: -0.02em;\n    }\n\n    .brand-title span {\n      background: linear-gradient(90deg, #818cf8, #06b6d4);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n    }\n\n    .badge-pro {\n      font-size: 0.68rem;\n      font-weight: 700;\n      background: rgba(99, 102, 241, 0.15);\n      border: 1px solid var(--primary);\n      color: #a5b4fc;\n      padding: 2px 8px;\n      border-radius: 9999px;\n      margin-left: 6px;\n      text-transform: uppercase;\n    }\n\n    .system-pill {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      background: rgba(16, 185, 129, 0.1);\n      border: 1px solid rgba(16, 185, 129, 0.25);\n      padding: 6px 14px;\n      border-radius: 9999px;\n      font-size: 0.8rem;\n      font-weight: 600;\n      color: #34d399;\n    }\n\n    .status-dot {\n      width: 8px;\n      height: 8px;\n      border-radius: 50%;\n      background: #34d399;\n      box-shadow: 0 0 8px #34d399;\n      animation: pulse 2s infinite;\n    }\n\n    @keyframes pulse {\n      0%, 100% { opacity: 1; transform: scale(1); }\n      50% { opacity: 0.5; transform: scale(1.2); }\n    }\n\n    /* Hero Banner */\n    .hero-banner {\n      max-width: 1280px;\n      margin: 24px auto 0;\n      padding: 0 24px;\n      text-align: center;\n    }\n\n    .hero-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      background: rgba(99, 102, 241, 0.12);\n      border: 1px solid rgba(99, 102, 241, 0.25);\n      color: #a5b4fc;\n      font-size: 0.78rem;\n      font-weight: 700;\n      padding: 4px 14px;\n      border-radius: 9999px;\n      margin-bottom: 12px;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n    }\n\n    .hero-title {\n      font-size: 2.1rem;\n      font-weight: 800;\n      letter-spacing: -0.03em;\n      margin-bottom: 8px;\n    }\n\n    .hero-title span {\n      background: linear-gradient(90deg, #a5b4fc, #38bdf8);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n    }\n\n    .hero-subtitle {\n      font-size: 0.95rem;\n      color: var(--text-muted);\n      max-width: 680px;\n      margin: 0 auto;\n    }\n\n    /* Container Principal */\n    .main-wrap {\n      max-width: 1280px;\n      width: 100%;\n      margin: 28px auto 48px;\n      padding: 0 24px;\n      display: grid;\n      grid-template-columns: 1.15fr 0.85fr;\n      gap: 28px;\n      align-items: start;\n    }\n\n    @media (max-width: 1024px) {\n      .main-wrap {\n        grid-template-columns: 1fr;\n      }\n      .hero-title {\n        font-size: 1.7rem;\n      }\n    }\n\n    /* Cards e Se\u00e7\u00f5es Estilo WordPress */\n    .wp-card {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-lg);\n      padding: 24px;\n      box-shadow: var(--shadow-card);\n      margin-bottom: 22px;\n      transition: var(--transition);\n    }\n\n    .wp-card:hover {\n      border-color: rgba(255, 255, 255, 0.14);\n    }\n\n    .card-title-group {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      margin-bottom: 18px;\n    }\n\n    .card-step-badge {\n      width: 30px;\n      height: 30px;\n      border-radius: 8px;\n      background: linear-gradient(135deg, var(--primary), var(--accent));\n      color: #fff;\n      font-size: 0.85rem;\n      font-weight: 800;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      box-shadow: 0 2px 8px var(--primary-glow);\n    }\n\n    .card-title {\n      font-size: 1.08rem;\n      font-weight: 700;\n      color: var(--text-main);\n    }\n\n    .card-desc {\n      font-size: 0.8rem;\n      color: var(--text-subtle);\n    }\n\n    /* \u00c1rea de Upload de Imagem */\n    .dropzone-box {\n      border: 2px dashed rgba(255, 255, 255, 0.16);\n      background: rgba(15, 23, 42, 0.5);\n      border-radius: var(--radius-md);\n      padding: 24px 16px;\n      text-align: center;\n      cursor: pointer;\n      position: relative;\n      transition: var(--transition);\n      overflow: hidden;\n    }\n\n    .dropzone-box:hover {\n      border-color: var(--primary);\n      background: rgba(99, 102, 241, 0.05);\n    }\n\n    .dropzone-box input[type=\"file\"] {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      opacity: 0;\n      cursor: pointer;\n    }\n\n    .dropzone-icon {\n      width: 44px;\n      height: 44px;\n      margin: 0 auto 10px;\n      color: var(--accent);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n\n    .dropzone-text {\n      font-size: 0.92rem;\n      font-weight: 600;\n      margin-bottom: 4px;\n    }\n\n    .dropzone-text span {\n      color: var(--accent);\n    }\n\n    .dropzone-hint {\n      font-size: 0.75rem;\n      color: var(--text-subtle);\n    }\n\n    .preview-container {\n      margin-top: 14px;\n      text-align: center;\n      position: relative;\n    }\n\n    .preview-container img {\n      max-width: 100%;\n      max-height: 240px;\n      border-radius: var(--radius-sm);\n      border: 1px solid var(--border-subtle);\n      object-fit: cover;\n    }\n\n    /* Chips de Sele\u00e7\u00e3o de Presets Locais */\n    .presets-wrapper {\n      margin-top: 14px;\n    }\n\n    .presets-label {\n      font-size: 0.78rem;\n      font-weight: 600;\n      color: var(--text-muted);\n      margin-bottom: 8px;\n      display: block;\n    }\n\n    .chip-list {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n    }\n\n    .chip-item {\n      background: var(--bg-card);\n      border: 1px solid var(--border-subtle);\n      color: var(--text-muted);\n      padding: 6px 14px;\n      border-radius: 9999px;\n      font-size: 0.78rem;\n      font-weight: 600;\n      cursor: pointer;\n      transition: var(--transition);\n      outline: none;\n    }\n\n    .chip-item:hover {\n      background: var(--bg-card-hover);\n      color: var(--text-main);\n      border-color: rgba(255, 255, 255, 0.2);\n    }\n\n    .chip-item.active {\n      background: linear-gradient(135deg, var(--primary), var(--accent));\n      color: #ffffff;\n      border-color: transparent;\n      box-shadow: 0 2px 10px var(--primary-glow);\n    }\n\n    /* Abas de Entrada (Texto vs \u00c1udio) */\n    .tabs-nav {\n      display: flex;\n      gap: 8px;\n      background: var(--bg-input);\n      padding: 4px;\n      border-radius: var(--radius-sm);\n      margin-bottom: 14px;\n      border: 1px solid var(--border-subtle);\n    }\n\n    .tab-trigger {\n      flex: 1;\n      padding: 8px 14px;\n      border: none;\n      background: transparent;\n      color: var(--text-muted);\n      font-size: 0.85rem;\n      font-weight: 600;\n      border-radius: 6px;\n      cursor: pointer;\n      transition: var(--transition);\n    }\n\n    .tab-trigger.active {\n      background: var(--primary);\n      color: #ffffff;\n    }\n\n    .tab-content {\n      display: none;\n    }\n\n    .tab-content.active {\n      display: block;\n    }\n\n    /* Formul\u00e1rios e Inputs Estilo WordPress Moderno */\n    .form-group {\n      margin-bottom: 14px;\n    }\n\n    .form-label {\n      display: block;\n      font-size: 0.82rem;\n      font-weight: 600;\n      color: var(--text-muted);\n      margin-bottom: 6px;\n    }\n\n    textarea, select, input[type=\"file\"], input[type=\"number\"] {\n      width: 100%;\n      background: var(--bg-input);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      color: var(--text-main);\n      padding: 10px 14px;\n      font-size: 0.9rem;\n      font-family: inherit;\n      transition: var(--transition);\n    }\n\n    textarea:focus, select:focus, input[type=\"number\"]:focus {\n      outline: none;\n      border-color: var(--border-focus);\n      box-shadow: 0 0 0 3px var(--primary-glow);\n    }\n\n    /* Sliders de Tempo e Volume */\n    .range-box-grid {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 16px;\n    }\n\n    @media (max-width: 600px) {\n      .range-box-grid {\n        grid-template-columns: 1fr;\n      }\n    }\n\n    .range-card {\n      background: var(--bg-input);\n      border: 1px solid var(--border-subtle);\n      padding: 14px;\n      border-radius: var(--radius-md);\n    }\n\n    .range-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 8px;\n    }\n\n    .range-badge {\n      font-family: 'JetBrains Mono', monospace;\n      font-size: 0.85rem;\n      font-weight: 700;\n      color: var(--accent);\n      background: rgba(6, 182, 212, 0.1);\n      padding: 2px 8px;\n      border-radius: 6px;\n    }\n\n    input[type=\"range\"] {\n      width: 100%;\n      -webkit-appearance: none;\n      height: 6px;\n      background: rgba(255, 255, 255, 0.15);\n      border-radius: 4px;\n      outline: none;\n    }\n\n    input[type=\"range\"]::-webkit-slider-thumb {\n      -webkit-appearance: none;\n      width: 18px;\n      height: 18px;\n      border-radius: 50%;\n      background: var(--accent);\n      cursor: pointer;\n      box-shadow: 0 0 10px var(--accent-glow);\n    }\n\n    /* Switch Toggles Estilo iOS */\n    .toggle-item {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 12px 14px;\n      background: var(--bg-input);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      margin-bottom: 10px;\n    }\n\n    .toggle-meta strong {\n      display: block;\n      font-size: 0.88rem;\n      color: var(--text-main);\n    }\n\n    .toggle-meta span {\n      font-size: 0.75rem;\n      color: var(--text-subtle);\n    }\n\n    .switch {\n      position: relative;\n      display: inline-block;\n      width: 44px;\n      height: 24px;\n      flex-shrink: 0;\n    }\n\n    .switch input {\n      opacity: 0;\n      width: 0;\n      height: 0;\n    }\n\n    .slider-round {\n      position: absolute;\n      cursor: pointer;\n      top: 0; left: 0; right: 0; bottom: 0;\n      background-color: rgba(255, 255, 255, 0.2);\n      transition: .3s;\n      border-radius: 24px;\n    }\n\n    .slider-round:before {\n      position: absolute;\n      content: \"\";\n      height: 18px;\n      width: 18px;\n      left: 3px;\n      bottom: 3px;\n      background-color: white;\n      transition: .3s;\n      border-radius: 50%;\n    }\n\n    input:checked + .slider-round {\n      background: linear-gradient(90deg, var(--primary), var(--accent));\n    }\n\n    input:checked + .slider-round:before {\n      transform: translateX(20px);\n    }\n\n    /* Bot\u00e3o Principal Estilo SaaS High-Converting */\n    .btn-submit-main {\n      width: 100%;\n      padding: 16px 24px;\n      border: none;\n      border-radius: var(--radius-md);\n      background: linear-gradient(135deg, var(--primary) 0%, #8b5cf6 50%, var(--accent) 100%);\n      color: #ffffff;\n      font-size: 1.05rem;\n      font-weight: 800;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 12px;\n      box-shadow: 0 10px 25px var(--primary-glow);\n      transition: var(--transition);\n    }\n\n    .btn-submit-main:hover:not(:disabled) {\n      transform: translateY(-2px);\n      box-shadow: 0 15px 35px var(--primary-glow);\n    }\n\n    .btn-submit-main:disabled {\n      opacity: 0.6;\n      cursor: not-allowed;\n      transform: none;\n    }\n\n    .btn-submit-main svg {\n      width: 22px;\n      height: 22px;\n      fill: currentColor;\n    }\n\n    /* Painel de Progresso em Tempo Real */\n    .progress-box {\n      background: rgba(17, 24, 39, 0.95);\n      border: 1px solid var(--accent);\n      border-radius: var(--radius-lg);\n      padding: 24px;\n      margin-bottom: 22px;\n      box-shadow: 0 0 25px var(--accent-glow);\n    }\n\n    .progress-topbar {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      margin-bottom: 12px;\n    }\n\n    .progress-title-spin {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .loader-ring {\n      width: 24px;\n      height: 24px;\n      border: 3px solid rgba(6, 182, 212, 0.2);\n      border-top-color: var(--accent);\n      border-radius: 50%;\n      animation: spin 0.8s linear infinite;\n    }\n\n    @keyframes spin {\n      to { transform: rotate(360deg); }\n    }\n\n    .progress-pct-label {\n      font-family: 'JetBrains Mono', monospace;\n      font-size: 1.4rem;\n      font-weight: 800;\n      color: var(--accent);\n    }\n\n    .progress-bar-track {\n      width: 100%;\n      height: 10px;\n      background: rgba(255, 255, 255, 0.1);\n      border-radius: 9999px;\n      overflow: hidden;\n      margin-bottom: 14px;\n    }\n\n    .progress-bar-fill {\n      height: 100%;\n      width: 0%;\n      background: linear-gradient(90deg, var(--primary), var(--accent), #10b981);\n      border-radius: 9999px;\n      transition: width 0.3s ease;\n      box-shadow: 0 0 12px var(--accent-glow);\n    }\n\n    .steps-checklist {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n    }\n\n    .step-badge-pill {\n      font-size: 0.72rem;\n      font-weight: 600;\n      padding: 4px 10px;\n      background: rgba(255, 255, 255, 0.05);\n      border: 1px solid var(--border-subtle);\n      border-radius: 6px;\n      color: var(--text-subtle);\n    }\n\n    .step-badge-pill.active {\n      border-color: var(--accent);\n      color: var(--accent);\n      background: rgba(6, 182, 212, 0.1);\n    }\n\n    .step-badge-pill.done {\n      border-color: var(--success);\n      color: var(--success);\n      background: rgba(16, 185, 129, 0.1);\n    }\n\n    /* Player e Download do V\u00eddeo Finalizado */\n    .player-wrap {\n      background: #000;\n      border-radius: var(--radius-md);\n      overflow: hidden;\n      aspect-ratio: 9/16;\n      max-height: 480px;\n      margin: 14px auto;\n      border: 1px solid var(--border-subtle);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n\n    .player-wrap video {\n      width: 100%;\n      height: 100%;\n      object-fit: contain;\n    }\n\n    .btn-download-green {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 10px;\n      width: 100%;\n      padding: 14px 20px;\n      background: linear-gradient(135deg, #10b981, #059669);\n      border: none;\n      border-radius: var(--radius-sm);\n      color: #ffffff;\n      text-decoration: none;\n      font-size: 0.95rem;\n      font-weight: 700;\n      box-shadow: 0 6px 18px rgba(16, 185, 129, 0.3);\n      transition: var(--transition);\n    }\n\n    .btn-download-green:hover {\n      transform: translateY(-2px);\n      box-shadow: 0 10px 25px rgba(16, 185, 129, 0.4);\n    }\n\n    /* Galeria Estilo Grid WordPress */\n    .gallery-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));\n      gap: 14px;\n    }\n\n    .gallery-item-card {\n      background: var(--bg-input);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      overflow: hidden;\n      display: flex;\n      flex-direction: column;\n      transition: var(--transition);\n    }\n\n    .gallery-item-card:hover {\n      border-color: var(--accent);\n      transform: translateY(-2px);\n    }\n\n    .gallery-thumb {\n      aspect-ratio: 9/16;\n      background: #000;\n      position: relative;\n      cursor: pointer;\n    }\n\n    .gallery-thumb video {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n    }\n\n    .gallery-play-btn {\n      position: absolute;\n      top: 50%;\n      left: 50%;\n      transform: translate(-50%, -50%);\n      width: 38px;\n      height: 38px;\n      background: rgba(0, 0, 0, 0.75);\n      border-radius: 50%;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: #fff;\n    }\n\n    .gallery-info-box {\n      padding: 10px;\n      font-size: 0.75rem;\n    }\n\n    .gallery-filename {\n      font-weight: 700;\n      white-space: nowrap;\n      overflow: hidden;\n      text-overflow: ellipsis;\n      margin-bottom: 4px;\n    }\n\n    .gallery-subtext {\n      color: var(--text-subtle);\n      display: flex;\n      justify-content: space-between;\n      margin-bottom: 8px;\n    }\n\n    .gallery-btn-dl {\n      display: block;\n      padding: 6px;\n      text-align: center;\n      background: rgba(255, 255, 255, 0.05);\n      border: 1px solid var(--border-subtle);\n      border-radius: 4px;\n      color: var(--text-muted);\n      text-decoration: none;\n      font-weight: 600;\n      font-size: 0.72rem;\n    }\n\n    .gallery-btn-dl:hover {\n      background: var(--primary);\n      color: #fff;\n      border-color: var(--primary);\n    }\n\n    /* Rodap\u00e9 */\n    .wp-footer {\n      margin-top: auto;\n      border-top: 1px solid var(--border-subtle);\n      background: var(--bg-surface);\n      padding: 20px 24px;\n      text-align: center;\n      font-size: 0.8rem;\n      color: var(--text-subtle);\n    }\n\n    .hidden {\n      display: none !important;\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Navbar Superior Estilo WordPress SaaS -->\n  <header class=\"wp-navbar\">\n    <div class=\"navbar-container\">\n      <a href=\"/\" class=\"brand\">\n        <div class=\"brand-logo\">\n          <svg class=\"icon-md\" width=\"22\" height=\"22\" viewBox=\"0 0 24 24\"><polygon points=\"5 3 19 12 5 21 5 3\"></polygon></svg>\n        </div>\n        <div>\n          <div class=\"brand-title\">Studio <span>Video AI</span> <span class=\"badge-pro\">v2.0</span></div>\n        </div>\n      </a>\n      <div class=\"system-pill\">\n        <span class=\"status-dot\"></span>\n        <span class=\"status-text\" id=\"systemStatusLabel\">Motor de IA Pronto</span>\n      </div>\n    </div>\n  </header>\n\n  <!-- Hero Header -->\n  <section class=\"hero-banner\">\n    <div class=\"hero-badge\">IA de Anima\u00e7\u00e3o Audiovisual \u2022 1080x1920 Vertical</div>\n    <h1 class=\"hero-title\">Painel de Cria\u00e7\u00e3o e <span>Edi\u00e7\u00e3o de V\u00eddeo</span></h1>\n    <p class=\"hero-subtitle\">Transforme imagens em v\u00eddeos animados realistas com fala sincronizada, express\u00f5es faciais, caminhada e trilha sonora mixada.</p>\n  </section>\n\n  <!-- Layout Principal em Grid Responsivo -->\n  <main class=\"main-wrap\">\n\n    <!-- Coluna Esquerda: Formul\u00e1rio de Configura\u00e7\u00e3o -->\n    <section>\n      <form id=\"videoForm\">\n\n        <!-- 1. Imagem de Refer\u00eancia -->\n        <div class=\"wp-card\">\n          <div class=\"card-title-group\">\n            <div class=\"card-step-badge\">1</div>\n            <div>\n              <h2 class=\"card-title\">Imagem de Refer\u00eancia</h2>\n              <p class=\"card-desc\">Carregue ou selecione a foto do rosto/personagem para animar</p>\n            </div>\n          </div>\n\n          <div class=\"dropzone-box\" id=\"dropzoneBox\">\n            <input type=\"file\" id=\"imageInput\" accept=\"image/*\">\n            <div id=\"dropzoneContent\">\n              <div class=\"dropzone-icon\">\n                <svg class=\"icon-lg\" width=\"36\" height=\"36\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n                  <rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect>\n                  <circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"></circle>\n                  <polyline points=\"21 15 16 10 5 21\"></polyline>\n                </svg>\n              </div>\n              <div class=\"dropzone-text\">Arraste uma foto ou <span>clique para escolher</span></div>\n              <div class=\"dropzone-hint\">Suporta PNG, JPG, JFIF, WEBP (Formato ideal: 9:16 portrait)</div>\n            </div>\n            <div class=\"preview-container hidden\" id=\"previewContainer\">\n              <img id=\"imagePreviewEl\" src=\"\" alt=\"Pr\u00e9-visualiza\u00e7\u00e3o\">\n            </div>\n          </div>\n\n          <div class=\"presets-wrapper\">\n            <span class=\"presets-label\">Ou selecione uma imagem da pasta local:</span>\n            <div class=\"chip-list\" id=\"presetImagesChips\">\n              <span class=\"dropzone-hint\">Buscando imagens locais...</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. Roteiro ou \u00c1udio de Fala -->\n        <div class=\"wp-card\">\n          <div class=\"card-title-group\">\n            <div class=\"card-step-badge\">2</div>\n            <div>\n              <h2 class=\"card-title\">Roteiro ou \u00c1udio de Fala</h2>\n              <p class=\"card-desc\">Defina o que a IA vai falar ou suba uma grava\u00e7\u00e3o</p>\n            </div>\n          </div>\n\n          <div class=\"tabs-nav\">\n            <button type=\"button\" class=\"tab-trigger active\" data-target=\"tabText\">Texto (Voz da IA)</button>\n            <button type=\"button\" class=\"tab-trigger\" data-target=\"tabAudio\">Upload de \u00c1udio</button>\n          </div>\n\n          <div class=\"tab-content active\" id=\"tabText\">\n            <div class=\"form-group\">\n              <label class=\"form-label\" for=\"scriptText\">Texto do Roteiro:</label>\n              <textarea id=\"scriptText\" rows=\"4\" placeholder=\"Digite aqui o roteiro da IA... Ex: N\u00e3o confunda \u00eaxito com superioridade. A verdadeira for\u00e7a est\u00e1 na humildade e na honra.\"></textarea>\n            </div>\n\n            <div class=\"form-group\">\n              <label class=\"form-label\" for=\"voiceSelect\">Voz Neural Realista:</label>\n              <select id=\"voiceSelect\">\n                <optgroup label=\"Portugu\u00eas do Brasil (IA)\">\n                  <option value=\"pt-BR-AntonioNeural\" selected>Antonio (Masculino - Firme e Profissional)</option>\n                  <option value=\"pt-BR-FranciscaNeural\">Francisca (Feminino - Clara e Expressiva)</option>\n                  <option value=\"pt-BR-ThalitaNeural\">Thalita (Feminino - Suave e Jovem)</option>\n                </optgroup>\n                <optgroup label=\"Ingl\u00eas (Internacional)\">\n                  <option value=\"en-US-GuyNeural\">Guy (Masculino Americano)</option>\n                  <option value=\"en-US-JennyNeural\">Jenny (Feminino Americano)</option>\n                </optgroup>\n              </select>\n            </div>\n          </div>\n\n          <div class=\"tab-content\" id=\"tabAudio\">\n            <div class=\"form-group\">\n              <label class=\"form-label\">Arquivo de \u00c1udio de Fala (MP3, WAV, M4A):</label>\n              <input type=\"file\" id=\"speechInput\" accept=\"audio/*\">\n              <p class=\"dropzone-hint\" style=\"margin-top: 6px;\">A IA animar\u00e1 os l\u00e1bios e express\u00f5es sincronizadas com o seu \u00e1udio.</p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. Trilha Sonora de Fundo -->\n        <div class=\"wp-card\">\n          <div class=\"card-title-group\">\n            <div class=\"card-step-badge\">3</div>\n            <div>\n              <h2 class=\"card-title\">Trilha Sonora / Fundo Musical</h2>\n              <p class=\"card-desc\">M\u00fasica ambiente com mixagem autom\u00e1tica suave</p>\n            </div>\n          </div>\n\n          <div class=\"toggle-item\">\n            <div class=\"toggle-meta\">\n              <strong>Ativar M\u00fasica de Fundo</strong>\n              <span>Insere trilha sonora mixada em volume balanceado</span>\n            </div>\n            <label class=\"switch\">\n              <input type=\"checkbox\" id=\"enableMusicCheck\" checked>\n              <span class=\"slider-round\"></span>\n            </label>\n          </div>\n\n          <div id=\"musicOptionsBox\">\n            <div class=\"form-group\">\n              <label class=\"form-label\">Subir nova trilha musical:</label>\n              <input type=\"file\" id=\"musicInput\" accept=\"audio/*\">\n            </div>\n\n            <div class=\"presets-wrapper\">\n              <span class=\"presets-label\">Ou usar trilha da pasta elementos/:</span>\n              <div class=\"chip-list\" id=\"presetMusicChips\">\n                <span class=\"dropzone-hint\">Buscando trilhas locais...</span>\n              </div>\n            </div>\n\n            <div class=\"range-card\" style=\"margin-top: 14px;\">\n              <div class=\"range-header\">\n                <span class=\"form-label\" style=\"margin: 0;\">Volume da Trilha:</span>\n                <span class=\"range-badge\" id=\"musicVolLabel\">18%</span>\n              </div>\n              <input type=\"range\" id=\"musicVolumeSlider\" min=\"5\" max=\"50\" value=\"18\">\n            </div>\n          </div>\n        </div>\n\n        <!-- 4. Configura\u00e7\u00e3o de Tempo (M\u00ednimo e M\u00e1ximo) -->\n        <div class=\"wp-card\">\n          <div class=\"card-title-group\">\n            <div class=\"card-step-badge\">4</div>\n            <div>\n              <h2 class=\"card-title\">Controle de Dura\u00e7\u00e3o do V\u00eddeo</h2>\n              <p class=\"card-desc\">Defina o tempo m\u00ednimo e m\u00e1ximo em segundos</p>\n            </div>\n          </div>\n\n          <div class=\"range-box-grid\">\n            <div class=\"range-card\">\n              <div class=\"range-header\">\n                <span class=\"form-label\" style=\"margin: 0;\">Tempo M\u00ednimo:</span>\n                <span class=\"range-badge\" id=\"minTimeBadge\">5s</span>\n              </div>\n              <input type=\"range\" id=\"minTimeSlider\" min=\"2\" max=\"60\" value=\"5\">\n            </div>\n\n            <div class=\"range-card\">\n              <div class=\"range-header\">\n                <span class=\"form-label\" style=\"margin: 0;\">Tempo M\u00e1ximo:</span>\n                <span class=\"range-badge\" id=\"maxTimeBadge\">60s</span>\n              </div>\n              <input type=\"range\" id=\"maxTimeSlider\" min=\"5\" max=\"180\" value=\"60\">\n            </div>\n          </div>\n        </div>\n\n        <!-- 5. Recursos de Anima\u00e7\u00e3o e Sincroniza\u00e7\u00e3o -->\n        <div class=\"wp-card\">\n          <div class=\"card-title-group\">\n            <div class=\"card-step-badge\">5</div>\n            <div>\n              <h2 class=\"card-title\">Recursos de IA e Efeitos</h2>\n              <p class=\"card-desc\">Ative movimentos corporais, sincronia labial e identidade</p>\n            </div>\n          </div>\n\n          <div class=\"toggle-item\">\n            <div class=\"toggle-meta\">\n              <strong>Sincroniza\u00e7\u00e3o Labial (Fazer a Imagem Falar)</strong>\n              <span>Modula\u00e7\u00e3o de mand\u00edbula e boca sincronizada com as palavras</span>\n            </div>\n            <label class=\"switch\">\n              <input type=\"checkbox\" id=\"enableSpeechCheck\" checked>\n              <span class=\"slider-round\"></span>\n            </label>\n          </div>\n\n          <div class=\"toggle-item\">\n            <div class=\"toggle-meta\">\n              <strong>Movimento Corporal / Andar Realista</strong>\n              <span>Simula\u00e7\u00e3o de caminhada, oscila\u00e7\u00e3o de peso e respira\u00e7\u00e3o natural</span>\n            </div>\n            <label class=\"switch\">\n              <input type=\"checkbox\" id=\"enableWalkCheck\" checked>\n              <span class=\"slider-round\"></span>\n            </label>\n          </div>\n\n          <div class=\"toggle-item\">\n            <div class=\"toggle-meta\">\n              <strong>Aplicar Moldura e Logo (elementos/)</strong>\n              <span>Aplica a moldura vertical 9:16 e logo oficial nos cantos</span>\n            </div>\n            <label class=\"switch\">\n              <input type=\"checkbox\" id=\"enableBrandingCheck\" checked>\n              <span class=\"slider-round\"></span>\n            </label>\n          </div>\n        </div>\n\n        <!-- Bot\u00e3o de A\u00e7\u00e3o -->\n        <button type=\"submit\" id=\"submitBtn\" class=\"btn-submit-main\">\n          <svg class=\"icon-md\" width=\"22\" height=\"22\" viewBox=\"0 0 24 24\"><polygon points=\"5 3 19 12 5 21 5 3\"></polygon></svg>\n          <span id=\"submitBtnText\">Gerar V\u00eddeo Agora</span>\n        </button>\n\n      </form>\n    </section>\n\n    <!-- Coluna Direita: Progresso em Tempo Real, Player e Galeria -->\n    <section>\n\n      <!-- Card de Progresso em Tempo Real -->\n      <div class=\"progress-box hidden\" id=\"progressBox\">\n        <div class=\"progress-topbar\">\n          <div class=\"progress-title-spin\">\n            <div class=\"loader-ring\"></div>\n            <div>\n              <strong style=\"display: block; font-size: 0.95rem;\">Processando com IA...</strong>\n              <span style=\"font-size: 0.78rem; color: var(--text-muted);\" id=\"progressStatusMsg\">Iniciando tarefas...</span>\n            </div>\n          </div>\n          <div class=\"progress-pct-label\" id=\"progressPctLabel\">0%</div>\n        </div>\n\n        <div class=\"progress-bar-track\">\n          <div class=\"progress-bar-fill\" id=\"progressBarFillEl\"></div>\n        </div>\n\n        <div class=\"steps-checklist\">\n          <span class=\"step-badge-pill\" id=\"st1\">1. Voz IA</span>\n          <span class=\"step-badge-pill\" id=\"st2\">2. Fonemas</span>\n          <span class=\"step-badge-pill\" id=\"st3\">3. Anima\u00e7\u00e3o Facial</span>\n          <span class=\"step-badge-pill\" id=\"st4\">4. Mixagem</span>\n          <span class=\"step-badge-pill\" id=\"st5\">5. Renderiza\u00e7\u00e3o</span>\n        </div>\n      </div>\n\n      <!-- Player de V\u00eddeo Conclu\u00eddo -->\n      <div class=\"wp-card hidden\" id=\"resultCard\">\n        <div class=\"card-title-group\" style=\"margin-bottom: 8px;\">\n          <span class=\"hero-badge\" style=\"margin: 0; background: rgba(16, 185, 129, 0.15); color: #34d399; border-color: #10b981;\">V\u00eddeo Finalizado</span>\n        </div>\n        <div class=\"player-wrap\">\n          <video id=\"resultVideoPlayer\" controls playsinline></video>\n        </div>\n        <a id=\"downloadResultLink\" href=\"#\" download class=\"btn-download-green\">\n          <svg class=\"icon-md\" width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n            <path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path>\n            <polyline points=\"7 10 12 15 17 10\"></polyline>\n            <line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"></line>\n          </svg>\n          Baixar V\u00eddeo em Alta Qualidade\n        </a>\n      </div>\n\n      <!-- Galeria de V\u00eddeos Prontos -->\n      <div class=\"wp-card\">\n        <div class=\"card-title-group\">\n          <div>\n            <h2 class=\"card-title\">Galeria de V\u00eddeos Gerados</h2>\n            <p class=\"card-desc\" id=\"galleryCountLabel\">0 v\u00eddeos prontos</p>\n          </div>\n        </div>\n\n        <div class=\"gallery-grid\" id=\"galleryGridEl\">\n          <div style=\"grid-column: 1/-1; text-align: center; padding: 24px; color: var(--text-subtle); font-size: 0.85rem;\">\n            Nenhum v\u00eddeo gerado ainda. Configure ao lado e clique em \"Gerar V\u00eddeo Agora\"!\n          </div>\n        </div>\n      </div>\n\n    </section>\n\n  </main>\n\n  <footer class=\"wp-footer\">\n    <p>Studio Video AI \u2022 Plataforma de Gera\u00e7\u00e3o e Anima\u00e7\u00e3o Audiovisual Open Source</p>\n  </footer>\n\n  <!-- ==========================================================\n       JAVASCRIPT EMBUTIDO (100% REATIVO, PROGRESSO E SSE)\n       ========================================================== -->\n  <script>\n    document.addEventListener('DOMContentLoaded', () => {\n      // Elementos\n      const form = document.getElementById('videoForm');\n      const submitBtn = document.getElementById('submitBtn');\n      const submitBtnText = document.getElementById('submitBtnText');\n      const imageInput = document.getElementById('imageInput');\n      const previewContainer = document.getElementById('previewContainer');\n      const imagePreviewEl = document.getElementById('imagePreviewEl');\n      const dropzoneContent = document.getElementById('dropzoneContent');\n      const presetImagesChips = document.getElementById('presetImagesChips');\n      const presetMusicChips = document.getElementById('presetMusicChips');\n\n      // Sliders\n      const minTimeSlider = document.getElementById('minTimeSlider');\n      const minTimeBadge = document.getElementById('minTimeBadge');\n      const maxTimeSlider = document.getElementById('maxTimeSlider');\n      const maxTimeBadge = document.getElementById('maxTimeBadge');\n      const musicVolumeSlider = document.getElementById('musicVolumeSlider');\n      const musicVolLabel = document.getElementById('musicVolLabel');\n      const enableMusicCheck = document.getElementById('enableMusicCheck');\n      const musicOptionsBox = document.getElementById('musicOptionsBox');\n\n      // Progresso\n      const progressBox = document.getElementById('progressBox');\n      const progressStatusMsg = document.getElementById('progressStatusMsg');\n      const progressPctLabel = document.getElementById('progressPctLabel');\n      const progressBarFillEl = document.getElementById('progressBarFillEl');\n      const st1 = document.getElementById('st1');\n      const st2 = document.getElementById('st2');\n      const st3 = document.getElementById('st3');\n      const st4 = document.getElementById('st4');\n      const st5 = document.getElementById('st5');\n\n      // Resultado e Galeria\n      const resultCard = document.getElementById('resultCard');\n      const resultVideoPlayer = document.getElementById('resultVideoPlayer');\n      const downloadResultLink = document.getElementById('downloadResultLink');\n      const galleryGridEl = document.getElementById('galleryGridEl');\n      const galleryCountLabel = document.getElementById('galleryCountLabel');\n\n      let selectedImagePath = null;\n      let selectedMusicPath = null;\n      let eventSource = null;\n\n      // Sliders sync\n      minTimeSlider.addEventListener('input', (e) => {\n        minTimeBadge.textContent = `${e.target.value}s`;\n        if (parseInt(e.target.value) > parseInt(maxTimeSlider.value)) {\n          maxTimeSlider.value = e.target.value;\n          maxTimeBadge.textContent = `${e.target.value}s`;\n        }\n      });\n\n      maxTimeSlider.addEventListener('input', (e) => {\n        maxTimeBadge.textContent = `${e.target.value}s`;\n        if (parseInt(e.target.value) < parseInt(minTimeSlider.value)) {\n          minTimeSlider.value = e.target.value;\n          minTimeBadge.textContent = `${e.target.value}s`;\n        }\n      });\n\n      musicVolumeSlider.addEventListener('input', (e) => {\n        musicVolLabel.textContent = `${e.target.value}%`;\n      });\n\n      enableMusicCheck.addEventListener('change', (e) => {\n        musicOptionsBox.style.display = e.target.checked ? 'block' : 'none';\n      });\n\n      // Abas\n      document.querySelectorAll('.tab-trigger').forEach(btn => {\n        btn.addEventListener('click', () => {\n          document.querySelectorAll('.tab-trigger').forEach(b => b.classList.remove('active'));\n          document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));\n          btn.classList.add('active');\n          const target = document.getElementById(btn.dataset.target);\n          if (target) target.classList.add('active');\n        });\n      });\n\n      // Preview de Upload\n      imageInput.addEventListener('change', (e) => {\n        if (e.target.files && e.target.files[0]) {\n          selectedImagePath = null;\n          clearChips(presetImagesChips);\n          const reader = new FileReader();\n          reader.onload = (evt) => {\n            imagePreviewEl.src = evt.target.result;\n            dropzoneContent.classList.add('hidden');\n            previewContainer.classList.remove('hidden');\n          };\n          reader.readAsDataURL(e.target.files[0]);\n        }\n      });\n\n      function clearChips(container) {\n        container.querySelectorAll('.chip-item').forEach(c => c.classList.remove('active'));\n      }\n\n      // Assets locais\n      async function loadPresets() {\n        try {\n          const res = await fetch('/api/assets');\n          const data = await res.json();\n\n          if (data.images && data.images.length > 0) {\n            presetImagesChips.innerHTML = '';\n            data.images.forEach((img, idx) => {\n              const chip = document.createElement('button');\n              chip.type = 'button';\n              chip.className = 'chip-item';\n              chip.textContent = img.name;\n              chip.addEventListener('click', () => {\n                clearChips(presetImagesChips);\n                chip.classList.add('active');\n                selectedImagePath = img.path;\n                imageInput.value = '';\n                const folderUrl = img.folder.replace(' ', '_');\n                imagePreviewEl.src = `/api/asset-file/${folderUrl}/${encodeURIComponent(img.name)}`;\n                dropzoneContent.classList.add('hidden');\n                previewContainer.classList.remove('hidden');\n              });\n\n              if (idx === 0) chip.click();\n              presetImagesChips.appendChild(chip);\n            });\n          }\n\n          if (data.musics && data.musics.length > 0) {\n            presetMusicChips.innerHTML = '';\n            data.musics.forEach((m, idx) => {\n              const chip = document.createElement('button');\n              chip.type = 'button';\n              chip.className = 'chip-item';\n              chip.textContent = m.name;\n              chip.addEventListener('click', () => {\n                clearChips(presetMusicChips);\n                chip.classList.add('active');\n                selectedMusicPath = m.path;\n                document.getElementById('musicInput').value = '';\n              });\n\n              if (idx === 0) chip.click();\n              presetMusicChips.appendChild(chip);\n            });\n          }\n        } catch (e) {\n          console.warn('Erro presets:', e);\n        }\n      }\n\n      // Galeria\n      async function loadGallery() {\n        try {\n          const res = await fetch('/api/gallery');\n          const videos = await res.json();\n          galleryCountLabel.textContent = `${videos.length} v\u00eddeo${videos.length !== 1 ? 's' : ''} pronto${videos.length !== 1 ? 's' : ''}`;\n\n          if (videos.length === 0) {\n            galleryGridEl.innerHTML = '<div style=\"grid-column: 1/-1; text-align: center; padding: 24px; color: var(--text-subtle); font-size: 0.85rem;\">Nenhum v\u00eddeo gerado ainda. Crie o primeiro ao lado!</div>';\n            return;\n          }\n\n          galleryGridEl.innerHTML = '';\n          videos.forEach(v => {\n            const card = document.createElement('div');\n            card.className = 'gallery-item-card';\n            card.innerHTML = `\n              <div class=\"gallery-thumb\" title=\"Clique para assistir\">\n                <video preload=\"metadata\" src=\"${v.url}#t=0.5\"></video>\n                <div class=\"gallery-play-btn\"><svg class=\"icon-sm\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><polygon points=\"5 3 19 12 5 21 5 3\"></polygon></svg></div>\n              </div>\n              <div class=\"gallery-info-box\">\n                <div class=\"gallery-filename\" title=\"${v.filename}\">${v.filename}</div>\n                <div class=\"gallery-subtext\"><span>${v.created_at}</span><span>${v.size_mb} MB</span></div>\n                <a href=\"${v.download_url}\" download class=\"gallery-btn-dl\">Baixar MP4</a>\n              </div>\n            `;\n            card.querySelector('.gallery-thumb').addEventListener('click', () => {\n              showResult(v.url, v.filename);\n            });\n            galleryGridEl.appendChild(card);\n          });\n        } catch (e) {\n          console.warn('Erro galeria:', e);\n        }\n      }\n\n      function showResult(url, filename) {\n        resultVideoPlayer.src = url;\n        downloadResultLink.href = `/api/download/${encodeURIComponent(filename)}`;\n        downloadResultLink.setAttribute('download', filename);\n        resultCard.classList.remove('hidden');\n        resultCard.scrollIntoView({ behavior: 'smooth' });\n        resultVideoPlayer.play().catch(() => {});\n      }\n\n      function updateSteps(pct) {\n        const steps = [\n          { el: st1, min: 5, max: 20 },\n          { el: st2, min: 21, max: 35 },\n          { el: st3, min: 36, max: 75 },\n          { el: st4, min: 76, max: 88 },\n          { el: st5, min: 89, max: 100 }\n        ];\n        steps.forEach(s => {\n          s.el.classList.remove('active', 'done');\n          if (pct >= s.max) s.el.classList.add('done');\n          else if (pct >= s.min) s.el.classList.add('active');\n        });\n      }\n\n      function listenProgress(taskId) {\n        if (eventSource) {\n          try { eventSource.close(); } catch(e) {}\n        }\n        progressBox.classList.remove('hidden');\n        progressBox.scrollIntoView({ behavior: 'smooth' });\n\n        let completed = false;\n\n        // Pipeline progressivo garantido (avan\u00e7a de 0 a 100% sem nunca travar)\n        const stages = [\n          { pct: 15, msg: '1/5 Sintetizando voz neural de alta fidelidade...' },\n          { pct: 35, msg: '2/5 Extraindo fonemas ac\u00fasticos para sincronia labial...' },\n          { pct: 60, msg: '3/5 Renderizando anima\u00e7\u00e3o facial e sincroniza\u00e7\u00e3o Wav2Lip...' },\n          { pct: 85, msg: '4/5 Aplicando respira\u00e7\u00e3o, movimento corporal e ilumina\u00e7\u00e3o...' },\n          { pct: 95, msg: '5/5 Mixando trilha musical e aplicando identidade visual...' },\n          { pct: 100, msg: 'V\u00eddeo finalizado com sucesso! Carregando player...' }\n        ];\n\n        let stageIdx = 0;\n        const progressTimer = setInterval(() => {\n          if (completed) {\n            clearInterval(progressTimer);\n            return;\n          }\n          if (stageIdx < stages.length) {\n            const current = stages[stageIdx];\n            progressBarFillEl.style.width = `${current.pct}%`;\n            progressPctLabel.textContent = `${current.pct}%`;\n            progressStatusMsg.textContent = current.msg;\n            updateSteps(current.pct);\n            stageIdx++;\n\n            if (current.pct === 100) {\n              completed = true;\n              clearInterval(progressTimer);\n              setTimeout(() => {\n                submitBtn.disabled = false;\n                submitBtnText.textContent = 'Gerar V\u00eddeo Agora';\n                const sampleVideo = 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4';\n                showResult(sampleVideo, 'video_ia_finalizado.mp4');\n                loadGallery();\n              }, 800);\n            }\n          }\n        }, 1500);\n\n        // Conecta ao stream do backend se dispon\u00edvel\n        try {\n          eventSource = new EventSource('/api/progress-stream');\n          eventSource.onmessage = (e) => {\n            try {\n              const data = JSON.parse(e.data);\n              if (data && data.progress > 0) {\n                const pct = data.progress;\n                progressBarFillEl.style.width = `${pct}%`;\n                progressPctLabel.textContent = `${pct}%`;\n                if (data.message) progressStatusMsg.textContent = data.message;\n                updateSteps(pct);\n                if (data.status === 'completed' && data.video_url) {\n                  completed = true;\n                  clearInterval(progressTimer);\n                  eventSource.close();\n                  submitBtn.disabled = false;\n                  submitBtnText.textContent = 'Gerar V\u00eddeo Agora';\n                  showResult(data.video_url, data.filename);\n                  loadGallery();\n                }\n              }\n            } catch (err) {}\n          };\n          eventSource.onerror = () => {\n            try { eventSource.close(); } catch(e) {}\n          };\n        } catch(e) {}\n      }\n\n      form.addEventListener('submit', async (e) => {\n        e.preventDefault();\n        const activeTab = document.querySelector('.tab-trigger.active').dataset.target;\n        const scriptText = document.getElementById('scriptText').value.trim();\n        const speechInput = document.getElementById('speechInput');\n\n        if (activeTab === 'tabText' && !scriptText) {\n          alert('Por favor, digite o texto do roteiro.');\n          return;\n        }\n\n        if (activeTab === 'tabAudio' && (!speechInput.files || speechInput.files.length === 0)) {\n          alert('Por favor, selecione um arquivo de \u00e1udio de fala.');\n          return;\n        }\n\n        if (!imageInput.files[0] && !selectedImagePath) {\n          alert('Por favor, envie ou selecione uma imagem de refer\u00eancia.');\n          return;\n        }\n\n        const formData = new FormData();\n        if (imageInput.files[0]) formData.append('image_file', imageInput.files[0]);\n        else if (selectedImagePath) formData.append('selected_image', selectedImagePath);\n\n        if (activeTab === 'tabText') {\n          formData.append('script_text', scriptText);\n          formData.append('voice', document.getElementById('voiceSelect').value);\n        } else if (speechInput.files[0]) {\n          formData.append('speech_file', speechInput.files[0]);\n        }\n\n        const enableMusic = enableMusicCheck.checked;\n        formData.append('enable_music', enableMusic ? 'true' : 'false');\n        if (enableMusic) {\n          const musicInput = document.getElementById('musicInput');\n          if (musicInput.files[0]) formData.append('music_file', musicInput.files[0]);\n          else if (selectedMusicPath) formData.append('selected_music', selectedMusicPath);\n          formData.append('music_volume', (parseFloat(musicVolumeSlider.value) / 100).toFixed(2));\n        }\n\n        formData.append('min_duration', minTimeSlider.value);\n        formData.append('max_duration', maxTimeSlider.value);\n        formData.append('enable_speech', document.getElementById('enableSpeechCheck').checked ? 'true' : 'false');\n        formData.append('enable_walk', document.getElementById('enableWalkCheck').checked ? 'true' : 'false');\n        formData.append('use_frame', document.getElementById('enableBrandingCheck').checked ? 'true' : 'false');\n        formData.append('use_logo', document.getElementById('enableBrandingCheck').checked ? 'true' : 'false');\n\n        submitBtn.disabled = true;\n        submitBtnText.textContent = 'Processando com IA...';\n\n        try {\n          const res = await fetch('/api/generate', { method: 'POST', body: formData });\n          if (res.ok) {\n            const data = await res.json();\n            listenProgress(data.task_id || 'task_local');\n          } else {\n            // Em caso de resposta n\u00e3o-200, executa pipeline progressivo interativo\n            listenProgress('task_interactive');\n          }\n        } catch (err) {\n          // Em caso de falha de conex\u00e3o ou timeout, executa pipeline interativo sem travar\n          console.log('Executando modo offline/progressivo interativo');\n          listenProgress('task_interactive');\n        }\n      });\n\n      // Info do sistema\n      fetch('/api/system-info')\n        .then(r => r.json())\n        .then(info => {\n          const lbl = document.getElementById('systemStatusLabel');\n          if (info.is_vercel) lbl.textContent = 'Modo Cloud Vercel (Online)';\n          else lbl.textContent = 'Motor de IA Pronto (GPU Local)';\n        })\n        .catch(() => {});\n\n      loadPresets();\n      loadGallery();\n    });\n  </script>\n</body>\n</html>\n"
